function PhotoPanel({ profile, update, onContinue, onBack }: { profile: SkinTuneProfile; update: (p: Partial<SkinTuneProfile>) => void; onContinue: () => void; onBack: () => void }) {
  const [status, setStatus] = useState<PhotoStatus>(profile.photoUrl ? 'good' : 'low-confidence');
  const [checking, setChecking] = useState(false);
  const diagnostic = diagnosticCopy[status];
  const pickFile = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => update({ photoUrl: String(reader.result) });
    reader.readAsDataURL(file);
    setStatus('low-confidence');
  };
  const runCheck = () => { setChecking(true); window.setTimeout(() => { setChecking(false); setStatus('good'); }, 700); };
  return <Shell profile={profile} onBack={onBack} onSettings={onBack} step={4} total={14}><div className="mx-auto max-w-3xl"><Intro eyebrow="04 / a gentle check" title="A photo helps us notice the details." body="This is only used to tune color and proportion suggestions. It is not a beauty score, identity check, or medical assessment.">
    <div className="mt-8 grid gap-6 md:grid-cols-[.84fr_1.16fr]">
      <div className="relative flex min-h-[300px] flex-col items-center justify-center overflow-hidden rounded-[1.5rem] border border-border bg-secondary/60 p-6">
        {profile.photoUrl ? <img src={profile.photoUrl} alt="Your uploaded portrait" data-testid="img-upload-preview" className="absolute inset-0 size-full object-cover" /> : <><div className="grid size-24 place-items-center rounded-full bg-card text-primary"><Camera size={34} /></div><p className="mt-4 text-center text-sm font-semibold">A natural, shoulders-up photo</p><p className="mt-1 text-center text-xs text-muted-foreground">No posing required.</p></>}
        <label className="focus-ring absolute bottom-4 inline-flex cursor-pointer items-center gap-2 rounded-full bg-card px-4 py-2.5 text-sm font-bold shadow-lg"><Upload size={15} /> {profile.photoUrl ? 'Choose another' : 'Choose a photo'}<input type="file" accept="image/*" onChange={pickFile} data-testid="input-photo" className="sr-only" /></label>
      </div>
      <div className={`rounded-[1.5rem] border p-6 ${diagnostic.good ? 'border-accent/30 bg-accent/8' : 'border-primary/25 bg-primary/5'}`}>
        <div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-muted-foreground">Photo check</p><h2 className="mt-3 font-serif text-2xl">{checking ? 'Taking a closer look…' : diagnostic.title}</h2></div>{checking ? <RefreshCw className="animate-spin text-primary" size={22} /> : diagnostic.good ? <CheckCircle2 className="text-accent" size={24} /> : <CircleHelp className="text-primary" size={24} />}</div>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground">{checking ? 'Checking light, framing, and clarity — nothing personal is stored here.' : diagnostic.body}</p>
        <div className="mt-6 flex flex-wrap gap-2"><span className="rounded-full bg-card px-3 py-1.5 text-xs font-semibold">{diagnostic.label}</span>{profile.photoUrl && <button type="button" onClick={runCheck} data-testid="button-run-photo-check" className="focus-ring rounded-full bg-primary px-3 py-1.5 text-xs font-bold text-primary-foreground">{checking ? 'Checking' : 'Run check again'}</button>}</div>
        <details className="mt-7 border-t border-border/70 pt-4"><summary className="flex cursor-pointer list-none items-center justify-between text-xs font-bold uppercase tracking-[.13em] text-muted-foreground">Preview helpful diagnostics <ChevronDown size={15} /></summary><div className="mt-3 grid grid-cols-2 gap-2">{(Object.keys(diagnosticCopy) as PhotoStatus[]).map((key) => <button type="button" key={key} onClick={() => setStatus(key)} data-testid={`button-diagnostic-${key}`} className={`focus-ring rounded-lg px-2 py-2 text-left text-xs transition ${status === key ? 'bg-primary text-primary-foreground' : 'bg-card hover:bg-secondary'}`}>{diagnosticCopy[key].label}</button>)}</div></details>
      </div>
    </div>
    <FooterActions onBack={onBack} onContinue={onContinue} disabled={!profile.photoUrl || !diagnostic.good} />
  </Intro></div></Shell>;
}

function LookVisual({ look, large = false }: { look: LookRecommendation; large?: boolean }) {
  return <div className={`relative overflow-hidden rounded-[1.4rem] bg-[#e4d6c4] ${large ? 'min-h-[390px]' : 'h-56'}`} data-image-url={look.imageUrl} aria-label={`${look.title} visual placeholder`}><div className="absolute inset-0 opacity-75" style={{ background: `radial-gradient(circle at 68% 21%, ${look.palette[1]} 0 8%, transparent 8.5%), linear-gradient(145deg, ${look.palette[2]} 0 38%, ${look.palette[0]} 38% 70%, #b78668 70%)` }} /><div className="absolute bottom-[-8%] left-[23%] h-[82%] w-[55%] rounded-t-[48%] bg-card/70 mix-blend-screen" /><div className="absolute left-[39%] top-[16%] size-[22%] rounded-full bg-[#b7785c]" /><div className="absolute bottom-[15%] left-1/2 h-[42%] w-[20%] -translate-x-1/2 rounded-[45%] bg-card/55" /><span className="absolute bottom-3 left-3 rounded-full bg-card/80 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.14em] text-foreground backdrop-blur">Image slot · ready to replace</span></div>;
}

function SkinTune() {
  const [screen, setScreen] = useState<Screen>(() => localStorage.getItem('skintune-profile') ? 'home' : 'welcome');
  const [profile, setProfile] = useState<SkinTuneProfile>(() => { try { return { ...initialProfile, ...JSON.parse(localStorage.getItem('skintune-profile') || '{}') }; } catch { return initialProfile; } });
  const [detailId, setDetailId] = useState('look-01');
  const [savedLooks, setSavedLooks] = useState<string[]>(() => JSON.parse(localStorage.getItem('skintune-saved-looks') || '[]'));
  const [feedback, setFeedback] = useState('');
  const [changeRequest, setChangeRequest] = useState('');
  const [generatedLooks, setGeneratedLooks] = useState<LookRecommendation[]>(looks);
  const [deletedNotice, setDeletedNotice] = useState(false);

  const update = (patch: Partial<SkinTuneProfile>) => setProfile((old) => ({ ...old, ...patch }));
  const index = screens.indexOf(screen);
  const go = (next: Screen) => { setScreen(next); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const back = () => { if (screen === 'detail' || screen === 'feedback') go('results'); else if (index > 0) go(screens[index - 1]); else go(profile.name ? 'home' : 'welcome'); };
  const saveProfile = () => { localStorage.setItem('skintune-profile', JSON.stringify(profile)); go('generating'); };
  const toggle = (key: keyof SkinTuneProfile, value: string, multi = true) => {
    if (!multi) { update({ [key]: value } as Partial<SkinTuneProfile>); return; }
    const values = (profile[key] as string[]) || [];
    update({ [key]: values.includes(value) ? values.filter((item) => item !== value) : [...values, value] } as Partial<SkinTuneProfile>);
  };
  const openSettings = () => go(profile.name ? 'settings' : 'welcome');

  useEffect(() => { if (screen !== 'generating') return; let active = true; generateLookImages(profile, { occasion: profile.occasion, details: profile.occasionDetails }, looks).then((result) => { if (active) { setGeneratedLooks(result); go('results'); } }); return () => { active = false; }; }, [screen]); // intentional: generation begins once
  useEffect(() => { localStorage.setItem('skintune-saved-looks', JSON.stringify(savedLooks)); }, [savedLooks]);

  const currentLook = useMemo(() => generatedLooks.find((item) => item.id === detailId) || generatedLooks[0], [generatedLooks, detailId]);
  if (screen === 'welcome') return <Welcome onStart={() => go('name')} onPrivacy={() => go('settings')} />;
  if (screen === 'home') return <Home profile={profile} savedLooks={savedLooks} onNew={() => { update({ photoUrl: '' }); go('name'); }} onResults={() => go('results')} onSettings={openSettings} onLook={(id) => { setDetailId(id); go('detail'); }} />;
  if (screen === 'settings') return <Settings profile={profile} deletedNotice={deletedNotice} onBack={() => go(profile.name ? 'home' : 'welcome')} onDelete={() => { localStorage.removeItem('skintune-profile'); localStorage.removeItem('skintune-saved-looks'); localStorage.removeItem('skintune-feedback'); setProfile(initialProfile); setDeletedNotice(true); setTimeout(() => go('welcome'), 900); }} />;
  if (screen === 'photo') return <PhotoPanel profile={profile} update={update} onContinue={() => go('appearance')} onBack={back} />;
  if (screen === 'results') return <Results profile={profile} looks={generatedLooks} savedLooks={savedLooks} onSave={(id) => setSavedLooks((old) => old.includes(id) ? old.filter((item) => item !== id) : [...old, id])} onLook={(id) => { setDetailId(id); go('detail'); }} onFeedback={() => go('feedback')} onBack={() => go('home')} />;
  if (screen === 'detail' && currentLook) return <LookDetail look={currentLook} saved={savedLooks.includes(currentLook.id)} onSave={() => setSavedLooks((old) => old.includes(currentLook.id) ? old.filter((item) => item !== currentLook.id) : [...old, currentLook.id])} onBack={back} onFeedback={() => go('feedback')} />;
  if (screen === 'feedback') return <Feedback value={feedback} setValue={setFeedback} request={changeRequest} setRequest={setChangeRequest} onBack={back} onDone={() => { localStorage.setItem('skintune-feedback', JSON.stringify({ feedback, changeRequest })); go('results'); }} />;
  if (screen === 'generating') return <Generating />;

  const continueTo: Record<string, Screen> = { name: 'profile', profile: 'consent', consent: 'photo', appearance: 'body', body: 'style', style: 'colors', colors: 'restrictions', restrictions: 'occasion', occasion: 'context', context: 'impression', impression: 'budget', budget: 'review', review: 'generating' };
  const screenContent: Record<string, ReactNode> = {
    name: <NameStep profile={profile} update={update} onNext={() => go('profile')} onBack={back} />,
    profile: <ProfileStep profile={profile} update={update} onNext={() => go('consent')} onBack={back} />,
    consent: <ConsentStep profile={profile} onNext={() => go('photo')} onBack={back} />,
    appearance: <AppearanceStep profile={profile} update={update} onNext={() => go('body')} onPhoto={() => go('photo')} onBack={back} />,
    body: <BodyStep profile={profile} update={update} onNext={() => go('style')} onBack={back} />,
    style: <StyleStep profile={profile} update={update} onNext={() => go('colors')} onBack={back} />,
    colors: <ColorsStep profile={profile} update={update} onNext={() => go('restrictions')} onBack={back} />,
    restrictions: <RestrictionsStep profile={profile} update={update} onNext={() => go('occasion')} onBack={back} />,
    occasion: <OccasionStep profile={profile} update={update} onNext={() => go('context')} onBack={back} />,
    context: <ContextStep profile={profile} update={update} onNext={() => go('impression')} onBack={back} />,
    impression: <ImpressionStep profile={profile} update={update} onNext={() => go('budget')} onBack={back} />,
    budget: <BudgetStep profile={profile} update={update} onNext={() => go('review')} onBack={back} />,
    review: <Review profile={profile} onEdit={(target) => go(target)} onSave={saveProfile} onBack={back} />,
  };
  return <>{screenContent[screen]}</>;
}

function StepShell({ profile, children, onBack, step, total = 14 }: { profile: SkinTuneProfile; children: ReactNode; onBack: () => void; step: number; total?: number }) {
  return <Shell profile={profile} onBack={onBack} onSettings={onBack} step={step} total={total}><div className="mx-auto max-w-2xl">{children}</div></Shell>;
}

function NameStep({ profile, update, onNext, onBack }: { profile: SkinTuneProfile; update: (p: Partial<SkinTuneProfile>) => void; onNext: () => void; onBack: () => void }) {
  return <StepShell profile={profile} onBack={onBack} step={1}><Intro eyebrow="01 / welcome in" title="First, what should we call you?" body="This is your space. Use your real name, a nickname, or simply a word that feels like you."><label className="block max-w-md"><span className="sr-only">Your name</span><input autoFocus value={profile.name} onChange={(e) => update({ name: e.target.value })} data-testid="input-name" placeholder="Your name" className="focus-ring w-full rounded-2xl border border-border bg-card px-5 py-4 text-xl outline-none placeholder:text-muted-foreground/55" /></label><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.name.trim()} /></Intro></StepShell>;
}

function ProfileStep({ profile, update, onNext, onBack }: { profile: SkinTuneProfile; update: (p: Partial<SkinTuneProfile>) => void; onNext: () => void; onBack: () => void }) {
  return <StepShell profile={profile} onBack={onBack} step={2}><Intro eyebrow="02 / a little context" title="Let’s make the advice feel like yours." body="Nothing here is a rulebook. It simply helps us choose language and proportions that feel comfortable."><div className="space-y-7"><div><p className="mb-3 text-sm font-bold">I’d like advice written for…</p><ChoiceGrid value={profile.pronouns} toggle={(v) => toggleValue(update, 'pronouns', v)} options={[{ label: 'Women’s styling' }, { label: 'Men’s styling' }, { label: 'Androgynous styling' }, { label: 'A mix of all three' }]} /></div><div><p className="mb-3 text-sm font-bold">My age range is…</p><ChoiceGrid value={profile.ageGroup} toggle={(v) => toggleValue(update, 'ageGroup', v)} options={[{ label: 'Under 25' }, { label: '25–34' }, { label: '35–49' }, { label: '50+' }, { label: 'Prefer not to say' }]} /></div><div><p className="mb-3 text-sm font-bold">Height <span className="font-normal text-muted-foreground">(optional)</span></p><input value={profile.height} onChange={(e) => update({ height: e.target.value })} data-testid="input-height" placeholder="e.g. 5' 7&quot;" className="focus-ring w-full rounded-xl border border-border bg-card px-4 py-3 outline-none sm:max-w-xs" /></div></div><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.pronouns || !profile.ageGroup} /></Intro></StepShell>;
}
function toggleValue(update: (p: Partial<SkinTuneProfile>) => void, key: keyof SkinTuneProfile, value: string) { update({ [key]: value } as Partial<SkinTuneProfile>); }

function ConsentStep({ profile, onNext, onBack }: { profile: SkinTuneProfile; onNext: () => void; onBack: () => void }) {
  return <StepShell profile={profile} onBack={onBack} step={3}><Intro eyebrow="03 / your choice" title="A portrait can make color guidance more precise." body="If you choose to share one, we’ll look at visible styling cues like light, contrast, and framing. SkinTune does not identify you, diagnose anything, or judge attractiveness."><div className="space-y-3"><div className="flex gap-4 rounded-2xl border border-border bg-card p-5"><ShieldCheck className="mt-0.5 shrink-0 text-accent" /><div><p className="font-semibold">You stay in control</p><p className="mt-1 text-sm leading-relaxed text-muted-foreground">Your photo stays in this browser prototype. Delete it any time from Privacy, plainly.</p></div></div><div className="flex gap-4 rounded-2xl border border-border bg-card p-5"><SlidersHorizontal className="mt-0.5 shrink-0 text-primary" /><div><p className="font-semibold">Guidance, not a verdict</p><p className="mt-1 text-sm leading-relaxed text-muted-foreground">Every suggestion is optional. Your taste and comfort come first.</p></div></div></div><FooterActions onBack={onBack} onContinue={onNext} label="I’m comfortable continuing" /></Intro></StepShell>;
}

function AppearanceStep({ profile, update, onNext, onPhoto, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={5}><Intro eyebrow="05 / what we noticed" title="Your appearance profile is ready." body="Think of this as a creative starting point, not a label. We’ll use it to build harmony, then let your preferences lead."><div className="rounded-[1.5rem] border border-accent/25 bg-accent/7 p-6"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-full bg-accent text-accent-foreground"><Check size={20} /></div><div><p className="font-semibold">Your Appearance Profile is Ready</p><p className="text-sm text-muted-foreground">A styling read based on your photo, not a verdict.</p></div></div><div className="mt-6 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-card p-4"><p className="text-xs uppercase tracking-wider text-muted-foreground">Skin tone</p><p className="mt-1 font-serif text-xl">{profile.appearance.skinTone}</p></div><div className="rounded-xl bg-card p-4"><p className="text-xs uppercase tracking-wider text-muted-foreground">Undertone</p><p className="mt-1 font-serif text-xl">{profile.appearance.undertone}</p></div><div className="rounded-xl bg-card p-4"><p className="text-xs uppercase tracking-wider text-muted-foreground">Confidence</p><p className="mt-1 font-serif text-xl">{profile.appearance.confidence}%</p></div></div><p className="mt-4 text-xs leading-relaxed text-muted-foreground">Analysis is based on your photo and is intended for styling recommendations.</p></div><button type="button" onClick={onPhoto} data-testid="button-change-photo" className="focus-ring mt-4 inline-flex items-center gap-2 text-sm font-semibold text-primary"><RotateCcw size={15} /> Use a different photo</button><FooterActions onBack={onBack} onContinue={onNext} /></Intro></StepShell>; }
function BodyStep({ profile, update, onNext, onBack }: any) { const opts = [{ label: 'Straight', description: 'A balanced line through shoulders and hips.' }, { label: 'Curved', description: 'A waist-led line with visible softness.' }, { label: 'Athletic', description: 'A stronger shoulder or torso line.' }, { label: 'I’m not sure', description: 'We’ll keep the fit advice flexible.' }]; return <StepShell profile={profile} onBack={onBack} step={6}><Intro eyebrow="06 / your canvas" title="How would you describe your build?" body="There’s no right answer. Pick what feels most useful when you get dressed."><ChoiceGrid value={profile.bodyBuild} toggle={(v) => toggleValue(update, 'bodyBuild', v)} options={opts} /><p className="mb-3 mt-8 text-sm font-bold">What should clothes do for you?</p><ChoiceGrid multi value={profile.fit} toggle={(v) => toggleKey(update, profile.fit, 'fit', v)} options={[{ label: 'Move with me' }, { label: 'Define my shape' }, { label: 'Create length' }, { label: 'Feel easy all day' }]} /><p className="mb-3 mt-8 text-sm font-bold">What matters most right now?</p><ChoiceGrid multi value={profile.priorities} toggle={(v) => toggleKey(update, profile.priorities, 'priorities', v)} options={[{ label: 'Versatility' }, { label: 'Feeling confident' }, { label: 'Comfort' }, { label: 'Looking memorable' }]} /><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.bodyBuild || !profile.fit.length || !profile.priorities.length} /></Intro></StepShell>; }
function toggleKey(update: (p: Partial<SkinTuneProfile>) => void, old: string[], key: keyof SkinTuneProfile, value: string) { update({ [key]: old.includes(value) ? old.filter((v) => v !== value) : [...old, value] } as Partial<SkinTuneProfile>); }
function StyleStep({ profile, update, onNext, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={7}><Intro eyebrow="07 / your point of view" title="Which style worlds pull you in?" body="Choose as many as you like. A personal style is usually a good sentence, not a single word."><ChoiceGrid multi value={profile.style} toggle={(v) => toggleKey(update, profile.style, 'style', v)} options={[{ label: 'Quiet luxury', description: 'Beautiful materials, low volume.' }, { label: 'Creative classic', description: 'Tailoring with a surprising detail.' }, { label: 'Soft minimal', description: 'Clean lines, gentle textures.' }, { label: 'Relaxed utility', description: 'Useful layers with personality.' }, { label: 'Romantic ease', description: 'Fluid shapes and a little movement.' }, { label: 'Bold eclectic', description: 'Color, pattern, and confident mixing.' }]} /><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.style.length} /></Intro></StepShell>; }
function ColorsStep({ profile, update, onNext, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={8}><Intro eyebrow="08 / your color language" title="Tell us what already feels like you." body="Your favorites matter more than any color theory. We’ll make the palette yours, not just technically flattering."><p className="mb-3 text-sm font-bold">I reach for… <span className="font-normal text-muted-foreground">choose up to five</span></p><ChoiceGrid multi value={profile.colorsLove} toggle={(v) => toggleKey(update, profile.colorsLove, 'colorsLove', v)} options={[{ label: 'Terracotta' }, { label: 'Cream' }, { label: 'Ink navy' }, { label: 'Olive' }, { label: 'Butter yellow' }, { label: 'Clear white' }, { label: 'Berry' }, { label: 'Chocolate' }]} /><p className="mb-3 mt-8 text-sm font-bold">I tend to avoid… <span className="font-normal text-muted-foreground">optional</span></p><div className="flex flex-wrap gap-2">{['Neon brights', 'Pastels', 'All black', 'Orange', 'Cool grey', 'Busy patterns'].map((item) => <button type="button" key={item} onClick={() => toggleKey(update, profile.colorsAvoid, 'colorsAvoid', item)} data-testid={`button-avoid-${item.toLowerCase().replace(' ', '-')}`} className={`focus-ring rounded-full border px-4 py-2.5 text-sm font-semibold transition ${profile.colorsAvoid.includes(item) ? 'border-foreground bg-foreground text-background' : 'border-border bg-card hover:border-primary/50'}`}>{item}</button>)}</div><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.colorsLove.length} /></Intro></StepShell>; }
function RestrictionsStep({ profile, update, onNext, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={9}><Intro eyebrow="09 / make it wearable" title="Anything we should work around?" body="These details help us make suggestions you can actually enjoy wearing. Skip anything that doesn’t apply."><ChoiceGrid multi value={profile.restrictions} toggle={(v) => toggleKey(update, profile.restrictions, 'restrictions', v)} options={[{ label: 'No wool or scratchy textures' }, { label: 'Comfortable shoes only' }, { label: 'Modest coverage' }, { label: 'Easy-care fabrics' }, { label: 'No dry cleaning' }, { label: 'None of these' }]} /><FooterActions onBack={onBack} onContinue={onNext} /></Intro></StepShell>; }
function OccasionStep({ profile, update, onNext, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={10}><Intro eyebrow="10 / the moment" title="Where are you getting dressed for?" body="A look should support the room you’re walking into, not distract you from being there."><ChoiceGrid value={profile.occasion} toggle={(v) => toggleValue(update, 'occasion', v)} options={[{ label: 'Everyday life', description: 'The outfits you repeat and rely on.' }, { label: 'Work or a meeting', description: 'Present, capable, still yourself.' }, { label: 'Dinner or drinks', description: 'A little more intention, never costume.' }, { label: 'A celebration', description: 'An occasion worth remembering.' }, { label: 'Travel', description: 'Beautiful, practical, ready to move.' }, { label: 'Something else', description: 'We’ll work it out together.' }]} /><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.occasion} /></Intro></StepShell>; }
function ContextStep({ profile, update, onNext, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={11}><Intro eyebrow="11 / set the scene" title="Give us the useful details." body="A sentence is plenty. Think weather, venue, dress code, and anything you want to feel in the room."><textarea autoFocus value={profile.occasionDetails} onChange={(e) => update({ occasionDetails: e.target.value })} data-testid="textarea-occasion-details" rows={5} placeholder="It’s a late-spring dinner at a small restaurant. I want to look considered but not overdressed." className="focus-ring w-full resize-none rounded-2xl border border-border bg-card p-5 leading-relaxed outline-none placeholder:text-muted-foreground/55" /><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.occasionDetails.trim()} /></Intro></StepShell>; }
function ImpressionStep({ profile, update, onNext, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={12}><Intro eyebrow="12 / the feeling" title="How do you want to come across?" body="Pick one or two. These words shape the balance between color, ease, and structure."><ChoiceGrid multi value={profile.impression} toggle={(v) => toggleKey(update, profile.impression, 'impression', v)} options={[{ label: 'Approachable' }, { label: 'Assured' }, { label: 'Creative' }, { label: 'Effortless' }, { label: 'Magnetic' }, { label: 'Grounded' }]} /><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.impression.length || profile.impression.length > 2} /></Intro></StepShell>; }
function BudgetStep({ profile, update, onNext, onBack }: any) { return <StepShell profile={profile} onBack={onBack} step={13}><Intro eyebrow="13 / keep it real" title="What feels comfortable for this edit?" body="We’ll use this as a guide for where to spend and where to save. It’s never a test of taste."><ChoiceGrid value={profile.budget} toggle={(v) => toggleValue(update, 'budget', v)} options={[{ label: '₹0–₹2K', description: 'Smart, accessible finds.' }, { label: '₹2K–₹5K', description: 'A mix of high-street and investment.' }, { label: '₹5K–₹10K', description: 'More room for fabric and construction.' }, { label: '₹10K–₹25K', description: 'More room for special pieces.' }, { label: '₹25K+', description: 'Keep the focus on the look.' }, { label: 'No strict budget', description: 'Show the best options for the direction.' }]} /><FooterActions onBack={onBack} onContinue={onNext} disabled={!profile.budget} /></Intro></StepShell>; }

function Review({ profile, onEdit, onSave, onBack }: { profile: SkinTuneProfile; onEdit: (s: Screen) => void; onSave: () => void; onBack: () => void }) { const rows: { label: string; value: string; target: Screen }[] = [{ label: 'Appearance', value: `${profile.appearance.skinTone} · ${profile.appearance.undertone} undertone · ${profile.appearance.confidence}% confidence`, target: 'appearance' }, { label: 'Profile', value: `${profile.pronouns} · ${profile.ageGroup}`, target: 'profile' }, { label: 'Build + fit', value: `${profile.bodyBuild} · ${profile.fit.join(', ')}`, target: 'body' }, { label: 'Style', value: profile.style.join(', '), target: 'style' }, { label: 'Colors', value: `Loves ${profile.colorsLove.join(', ')}${profile.colorsAvoid.length ? ` · avoids ${profile.colorsAvoid.join(', ')}` : ''}`, target: 'colors' }, { label: 'Moment', value: `${profile.occasion} · ${profile.occasionDetails}`, target: 'occasion' }, { label: 'Impression', value: `${profile.impression.join(', ')} · ${profile.budget}`, target: 'impression' }]; return <StepShell profile={profile} onBack={onBack} step={14}><Intro eyebrow="14 / your edit, at a glance" title={`This sounds like ${profile.name}.`} body="Look it over, make any changes, then we’ll make five complete looks around it."><div className="divide-y divide-border overflow-hidden rounded-[1.5rem] border border-border bg-card">{rows.map((row) => <div key={row.label} className="flex items-start justify-between gap-4 p-5"><div className="min-w-0"><p className="text-xs font-bold uppercase tracking-[.13em] text-muted-foreground">{row.label}</p><p className="mt-1 line-clamp-2 text-sm leading-relaxed">{row.value}</p></div><button type="button" onClick={() => onEdit(row.target)} data-testid={`button-edit-${row.label.toLowerCase().replace(' ', '-')}`} className="focus-ring inline-flex shrink-0 items-center gap-1.5 rounded-full px-3 py-2 text-xs font-bold text-primary hover:bg-secondary"><Pencil size={13} /> Edit</button></div>)}</div><FooterActions onBack={onBack} onContinue={onSave} label="Make my five looks" /></Intro></StepShell>; }

function Generating() { const stages = ['Reading the room', 'Balancing your palette', 'Building complete outfits', 'Adding the details that make them yours']; const [active, setActive] = useState(0); useEffect(() => { const timer = window.setInterval(() => setActive((value) => Math.min(value + 1, 3)), 640); return () => window.clearInterval(timer); }, []); return <div className="noise min-h-[100dvh] bg-[#273e3b] text-[#f7eddf]"><div className="mx-auto flex min-h-[100dvh] max-w-3xl flex-col justify-center px-6 py-16"><div className="mb-14 flex items-center gap-2"><span className="grid size-10 place-items-center rounded-[14px] bg-[#dc7456]"><Sparkles size={19} /></span><span className="font-serif text-2xl">SkinTune</span></div><p className="text-xs font-bold uppercase tracking-[.24em] text-[#efad87]">Your personal edit</p><h1 className="mt-5 max-w-xl font-serif text-[clamp(3rem,8vw,6.5rem)] leading-[.88] tracking-[-.05em]">Making room<br />for your <em className="text-[#efad87]">point of view.</em></h1><div className="mt-16 max-w-md space-y-4">{stages.map((stage, index) => <div key={stage} className={`flex items-center gap-4 transition duration-500 ${index <= active ? 'opacity-100' : 'opacity-30'}`}><span className={`grid size-8 place-items-center rounded-full border ${index < active ? 'border-[#efad87] bg-[#efad87] text-[#273e3b]' : 'border-[#f7eddf]/40'}`}>{index < active ? <Check size={15} /> : index === active ? <span className="size-2 animate-pulse rounded-full bg-[#efad87]" /> : <span className="size-1.5 rounded-full bg-[#f7eddf]/50" />}</span><span className="text-sm font-semibold">{stage}</span></div>)}</div><p className="mt-12 flex items-center gap-2 text-xs text-[#f7eddf]/65"><Clock3 size={14} /> Usually takes less than a minute</p></div></div>; }

function Home({ profile, savedLooks, onNew, onResults, onSettings, onLook }: { profile: SkinTuneProfile; savedLooks: string[]; onNew: () => void; onResults: () => void; onSettings: () => void; onLook: (id: string) => void }) {
  return <div className="noise min-h-[100dvh]"><Header onSettings={onSettings} name={profile.name} /><main className="mx-auto max-w-6xl px-4 py-10 sm:px-8 sm:py-16"><div className="grid gap-10 lg:grid-cols-[1.1fr_.9fr] lg:items-end"><div className="animate-rise"><p className="text-xs font-bold uppercase tracking-[.22em] text-primary">Your styling journal</p><h1 className="mt-4 max-w-2xl font-serif text-[clamp(3rem,7vw,6.2rem)] leading-[.88] tracking-[-.05em]">Good to see you,<br /><em className="text-primary">{profile.name}.</em></h1><p className="mt-6 max-w-lg text-lg leading-relaxed text-muted-foreground">Your edit is saved. Pick up where you left off, or open a fresh moment to get dressed for.</p><div className="mt-8 flex flex-wrap gap-3"><button type="button" onClick={onResults} data-testid="button-view-looks" className="focus-ring inline-flex items-center gap-2 rounded-full bg-primary px-6 py-3.5 text-sm font-bold text-primary-foreground shadow-lg">View your five looks <ArrowRight size={16} /></button><button type="button" onClick={onNew} data-testid="button-new-edit" className="focus-ring inline-flex items-center gap-2 rounded-full border border-border bg-card px-6 py-3.5 text-sm font-bold hover:border-primary/50"><RefreshCw size={16} /> New edit</button></div></div><div className="soft-grid relative overflow-hidden rounded-[1.7rem] border border-border bg-secondary/60 p-7"><div className="absolute -right-14 -top-14 size-48 rounded-full bg-primary/15 blur-2xl" /><p className="relative text-xs font-bold uppercase tracking-[.16em] text-muted-foreground">Your signature direction</p><h2 className="relative mt-3 font-serif text-3xl">Warm, considered, quietly magnetic.</h2><div className="relative mt-7 flex items-end gap-2"><div className="h-20 w-12 rounded-t-full bg-[#d58e6e]" /><div className="h-28 w-12 rounded-t-full bg-[#283d3b]" /><div className="h-16 w-12 rounded-t-full bg-[#e5c99f]" /><div className="h-24 w-12 rounded-t-full bg-[#a84f3c]" /></div><p className="relative mt-6 text-sm leading-relaxed text-muted-foreground">Your saved palette leans into warmth and depth, with room for one clear surprise.</p></div></div>{savedLooks.length > 0 && <section className="mt-20"><div className="flex items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">Saved for later</p><h2 className="mt-2 font-serif text-3xl">Your keepers</h2></div><button type="button" onClick={onResults} data-testid="button-see-all-saved" className="focus-ring text-sm font-bold text-primary">See all <ArrowRight className="ml-1 inline" size={15} /></button></div><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{savedLooks.map((id) => { const look = looks.find((item) => item.id === id); return look && <button type="button" key={id} onClick={() => onLook(id)} data-testid={`card-saved-look-${id}`} className="focus-ring rounded-[1.3rem] border border-border bg-card p-2 text-left transition hover:-translate-y-1"><LookVisual look={look} /><p className="px-3 pb-2 pt-3 font-serif text-xl">{look.title}</p></button>; })}</div></section>}</main></div>;
}

function Results({ profile, looks: resultLooks, savedLooks, onSave, onLook, onFeedback, onBack }: { profile: SkinTuneProfile; looks: LookRecommendation[]; savedLooks: string[]; onSave: (id: string) => void; onLook: (id: string) => void; onFeedback: () => void; onBack: () => void }) {
  return <Shell profile={profile} onBack={onBack} onSettings={onBack}><div className="animate-rise"><div className="flex flex-wrap items-end justify-between gap-6"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-primary">Your five looks</p><h1 className="mt-3 font-serif text-[clamp(2.8rem,6vw,5.4rem)] leading-[.9] tracking-[-.05em]">A wardrobe of<br /><em className="text-primary">possibilities.</em></h1></div><button type="button" onClick={onFeedback} data-testid="button-request-changes" className="focus-ring inline-flex items-center gap-2 rounded-full border border-border bg-card px-4 py-3 text-sm font-bold hover:border-primary/50"><SlidersHorizontal size={16} /> Change the direction</button></div><p className="mt-6 max-w-xl text-muted-foreground">Built for {profile.occasion.toLowerCase()} with a {profile.impression.join(' and ').toLowerCase()} energy. Nothing here is a rule — just five places to begin.</p><div className="mt-10 grid gap-6 md:grid-cols-2 lg:grid-cols-3">{resultLooks.map((look, index) => <article key={look.id} className={`group rounded-[1.45rem] border border-border bg-card p-2 shadow-[0_8px_30px_hsl(var(--foreground)/.04)] ${index === 0 ? 'md:col-span-2 lg:col-span-2' : ''}`}><button type="button" onClick={() => onLook(look.id)} data-testid={`card-look-${look.id}`} className="focus-ring block w-full text-left"><LookVisual look={look} large={index === 0} /><div className="p-4 pb-3"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-primary">{index === 0 ? 'Best match' : `Look ${String(index + 1).padStart(2, '0')}`}</p><h2 className="mt-1 font-serif text-2xl">{look.title}</h2></div><ChevronRight className="mt-2 text-muted-foreground transition group-hover:translate-x-1" size={20} /></div><p className="mt-2 text-sm text-muted-foreground">{look.note}</p><dl className="mt-5 grid gap-x-4 gap-y-3 border-t border-border/70 pt-4 sm:grid-cols-2"><div><dt className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Outfit</dt><dd className="mt-1 text-sm leading-snug">{look.outfit}</dd></div><div><dt className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Jewellery</dt><dd className="mt-1 text-sm leading-snug">{look.jewellery}</dd></div><div><dt className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Hairstyle</dt><dd className="mt-1 text-sm leading-snug">{look.hairstyle}</dd></div><div><dt className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Makeup</dt><dd className="mt-1 text-sm leading-snug">{look.makeup}</dd></div></dl></div></button><div className="flex items-center justify-between border-t border-border/70 px-4 py-3"><span className="flex items-center gap-2"><span className="flex gap-1.5">{look.palette.map((color) => <i key={color} className="size-4 rounded-full border border-card shadow-sm" style={{ backgroundColor: color }} />)}</span><span className="text-xs font-semibold text-muted-foreground">{look.confidence}% confidence</span></span><button type="button" onClick={() => onSave(look.id)} data-testid={`button-save-${look.id}`} className={`focus-ring inline-flex items-center gap-1.5 rounded-full px-3 py-2 text-xs font-bold ${savedLooks.includes(look.id) ? 'bg-secondary text-foreground' : 'text-muted-foreground hover:bg-secondary'}`}>{savedLooks.includes(look.id) ? <Check size={14} /> : <Heart size={14} />} {savedLooks.includes(look.id) ? 'Saved' : 'Save'}</button></div></article>)}</div><div className="mt-10 rounded-2xl border border-border bg-secondary/55 p-5 text-sm text-muted-foreground"><div className="flex items-start gap-3"><Info size={17} className="mt-0.5 shrink-0 text-primary" /><p>These looks are starting points shaped around your answers. Keep what feels like you, skip what doesn’t, and tell us what to change.</p></div></div></div></Shell>;
}

function LookDetail({ look, saved, onSave, onBack, onFeedback }: { look: LookRecommendation; saved: boolean; onSave: () => void; onBack: () => void; onFeedback: () => void }) { return <div className="noise min-h-[100dvh]"><Header onBack={onBack} onSettings={onBack} /><main className="mx-auto max-w-6xl px-4 py-8 sm:px-8 sm:py-14"><div className="grid gap-8 lg:grid-cols-[.9fr_1.1fr] lg:items-start"><LookVisual look={look} large /><div className="animate-rise lg:pt-4"><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">The complete look</p><h1 className="mt-4 font-serif text-[clamp(3rem,7vw,6rem)] leading-[.86] tracking-[-.05em]">{look.title}</h1><p className="mt-6 max-w-md text-lg leading-relaxed text-muted-foreground">{look.note}</p><div className="mt-7 flex items-center gap-3"><div className="flex gap-2">{look.palette.map((color) => <span key={color} className="size-8 rounded-full border-2 border-card shadow-sm" style={{ backgroundColor: color }} />)}</div><span className="rounded-full bg-secondary px-3 py-1.5 text-xs font-bold">{look.confidence}% confidence</span></div><div className="mt-10 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl border border-border bg-card p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Outfit</p><p className="mt-2 font-semibold">{look.outfit}</p></div><div className="rounded-2xl border border-border bg-card p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Colour direction</p><p className="mt-2 text-sm leading-relaxed">These shades create a warm, grounded balance around your {look.palette.length}-tone palette.</p></div><div className="rounded-2xl border border-border bg-card p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Jewellery</p><p className="mt-2 font-semibold">{look.jewellery}</p></div><div className="rounded-2xl border border-border bg-card p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Hairstyle</p><p className="mt-2 font-semibold">{look.hairstyle}</p></div><div className="rounded-2xl border border-border bg-card p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Makeup</p><p className="mt-2 font-semibold">{look.makeup}</p></div><div className="rounded-2xl border border-border bg-card p-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Footwear + accessories</p><p className="mt-2 text-sm leading-relaxed">{look.footwear} {look.accessories}</p></div></div><div className="mt-8 rounded-2xl border border-accent/25 bg-accent/7 p-5"><p className="font-serif text-2xl">Why SkinTune chose this</p><ul className="mt-4 grid gap-2 text-sm text-muted-foreground sm:grid-cols-2"><li className="flex gap-2"><Check size={16} className="shrink-0 text-accent" /> Matches your appearance profile</li><li className="flex gap-2"><Check size={16} className="shrink-0 text-accent" /> Fits your preferred style</li><li className="flex gap-2"><Check size={16} className="shrink-0 text-accent" /> Suits the occasion and setting</li><li className="flex gap-2"><Check size={16} className="shrink-0 text-accent" /> Supports the impression you want</li></ul></div><div className="mt-6 divide-y divide-border border-y border-border">{look.pieces.map((piece) => <div key={piece.category} className="grid grid-cols-[72px_1fr] gap-4 py-4"><p className="text-xs font-bold uppercase tracking-wider text-muted-foreground">{piece.category}</p><div><p className="font-semibold">{piece.name}</p><p className="mt-1 text-sm leading-relaxed text-muted-foreground">{piece.detail}</p></div></div>)}</div><p className="mt-5 text-xs leading-relaxed text-muted-foreground">Visual preview is a style visualisation. It does not guarantee exact fit, fabric fall, or real-world colour.</p><div className="mt-8 flex flex-wrap gap-3"><button type="button" onClick={onSave} data-testid="button-detail-save" className={`focus-ring inline-flex items-center gap-2 rounded-full px-5 py-3 text-sm font-bold ${saved ? 'bg-secondary' : 'bg-primary text-primary-foreground'}`}>{saved ? <Check size={16} /> : <Save size={16} />} {saved ? 'Saved to your journal' : 'Save this look'}</button><button type="button" onClick={onFeedback} data-testid="button-detail-not-for-me" className="focus-ring inline-flex items-center gap-2 rounded-full border border-border bg-card px-5 py-3 text-sm font-bold hover:border-primary/50"><X size={16} /> Not for me</button></div></div></div></main></div>; }

function Feedback({ value, setValue, request, setRequest, onBack, onDone }: { value: string; setValue: (v: string) => void; request: string; setRequest: (v: string) => void; onBack: () => void; onDone: () => void }) { return <div className="noise min-h-[100dvh]"><Header onBack={onBack} onSettings={onBack} /><main className="mx-auto max-w-2xl px-4 py-12 sm:px-8 sm:py-20"><Intro eyebrow="A better next edit" title="What should feel different?" body="Your no is useful. Tell us what missed, and we’ll keep your taste at the center."><div className="grid gap-3 sm:grid-cols-2">{['Too formal', 'Not enough color', 'Not comfortable', 'Not my style', 'Too much going on', 'The proportions feel off'].map((item) => <OptionCard key={item} label={item} selected={value === item} onClick={() => setValue(value === item ? '' : item)} />)}</div><label className="mt-7 block"><span className="mb-2 block text-sm font-bold">Anything else? <span className="font-normal text-muted-foreground">optional</span></span><textarea value={request} onChange={(e) => setRequest(e.target.value)} data-testid="textarea-change-request" rows={4} placeholder="More relaxed, fewer layers, a little brighter…" className="focus-ring w-full resize-none rounded-2xl border border-border bg-card p-4 outline-none placeholder:text-muted-foreground/55" /></label><FooterActions onBack={onBack} onContinue={onDone} label="Save feedback" /></Intro></main></div>; }

function Settings({ profile, onBack, onDelete, deletedNotice }: { profile: SkinTuneProfile; onBack: () => void; onDelete: () => void; deletedNotice: boolean }) { const [confirm, setConfirm] = useState(false); return <div className="noise min-h-[100dvh]"><Header onBack={onBack} onSettings={onBack} name={profile.name} /><main className="mx-auto max-w-2xl px-4 py-12 sm:px-8 sm:py-20"><p className="text-xs font-bold uppercase tracking-[.2em] text-primary">Privacy, plainly</p><h1 className="mt-4 font-serif text-5xl tracking-[-.04em]">Your space, your call.</h1><p className="mt-5 leading-relaxed text-muted-foreground">SkinTune is a frontend prototype. Your profile and feedback live only in this browser’s local storage. There is no account, server upload, or hidden score.</p><div className="mt-10 space-y-3"><div className="flex gap-4 rounded-2xl border border-border bg-card p-5"><LockKeyhole className="shrink-0 text-accent" /><div><p className="font-semibold">Photo privacy</p><p className="mt-1 text-sm leading-relaxed text-muted-foreground">Your selected photo is used to show your preview in this browser. A future production version should use explicit retention controls before any upload.</p></div></div><div className="flex gap-4 rounded-2xl border border-border bg-card p-5"><FileText className="shrink-0 text-primary" /><div><p className="font-semibold">What we remember</p><p className="mt-1 text-sm leading-relaxed text-muted-foreground">Your choices, saved looks, and feedback stay available so returning to SkinTune feels continuous.</p></div></div></div><div className="mt-10 rounded-2xl border border-destructive/25 bg-destructive/5 p-5"><div className="flex items-start gap-4"><Trash2 className="mt-0.5 shrink-0 text-destructive" /><div className="flex-1"><p className="font-semibold">Delete my SkinTune data</p><p className="mt-1 text-sm leading-relaxed text-muted-foreground">Remove your saved profile, photo preview, saved looks, and feedback from this browser.</p>{deletedNotice ? <p className="mt-4 flex items-center gap-2 text-sm font-bold text-accent"><CheckCircle2 size={16} /> Data deleted. Taking you back to the beginning…</p> : confirm ? <div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={onDelete} data-testid="button-confirm-delete" className="focus-ring rounded-full bg-destructive px-4 py-2.5 text-sm font-bold text-destructive-foreground">Yes, delete everything</button><button type="button" onClick={() => setConfirm(false)} data-testid="button-cancel-delete" className="focus-ring rounded-full bg-card px-4 py-2.5 text-sm font-bold">Keep my data</button></div> : <button type="button" onClick={() => setConfirm(true)} data-testid="button-delete-data" className="focus-ring mt-4 rounded-full border border-destructive/40 px-4 py-2.5 text-sm font-bold text-destructive hover:bg-destructive/10">Delete my data</button>}</div></div></div><button type="button" onClick={onBack} data-testid="button-settings-done" className="focus-ring mt-8 inline-flex items-center gap-2 rounded-full bg-primary px-6 py-3 font-bold text-primary-foreground">Back to my journal <ArrowRight size={16} /></button></main></div>; }

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><ErrorBoundary resetKey="skintune"><SkinTune /></ErrorBoundary><Toaster /></TooltipProvider></QueryClientProvider>; }

export default App;